parameters.jsCode:
const raw = $input.first().json;
const out = raw.output || raw;
const pool = $('Aggregate Insight Evidence').first().json.quotes || [];
const base = $('Loop Insights').first().json;
const keyOf = (sa, q) => String(sa) + '||' + String(q);
const poolMap = new Map();
for (const p of pool) { poolMap.set(keyOf(p.session_answer_id, p.quote), p); }
const picked = [];
const seen = new Set();
// The same verbatim moment can sit under two session_answer_ids (one quote
// evidencing two questions). clip has a unique (insight, moment) constraint,
// so dedupe by moment as well or the insert fails mid-loop.
const momentSeen = new Set();
let droppedNoTimestamp = 0;
let droppedDupMoment = 0;
for (const s of (out.quotes || [])) {
  const k = keyOf(s.session_answer_id, s.quote);
  if (!poolMap.has(k) || seen.has(k)) { continue; }
  seen.add(k);
  const p = poolMap.get(k);
  // clip.start_time and clip.end_time are NOT NULL. A quote without word-level
  // timestamps cannot become a clip, so drop it here rather than let the insert
  // fail mid-loop.
  if (p.start_time === null || p.start_time === undefined || p.end_time === null || p.end_time === undefined) { droppedNoTimestamp++; continue; }
  const mk = String(p.session_id) + '|' + String(p.start_time) + '|' + String(p.end_time);
  if (momentSeen.has(mk)) { droppedDupMoment++; continue; }
  momentSeen.add(mk);
  picked.push({ session_answer_id: p.session_answer_id, session_id: p.session_id, quote: p.quote, start_time: p.start_time, end_time: p.end_time });
}
const sessions = new Set();
for (const p of pool) { sessions.add(String(p.session_id)); }
const sessionsCount = sessions.size;
const questionsCount = base.questions_count;
const findingsCount = base.findings_count;

// Corroboration is PROPORTIONAL to the cohort. The old absolute thresholds
// (3 sessions = strong) were written for a small study: on a 22-participant
// project that is 14% of people, so 22 of 25 insights read 'strong' and the
// column separated nothing. The question floors stay, so an insight resting on
// a single question cannot reach 'strong' on session breadth alone.
const cohort = Number((pool[0] || {}).project_sessions) || 0;
let corroboration;
if (cohort > 0) {
  const share = sessionsCount / cohort;
  corroboration = (share >= 0.75 && questionsCount >= 3) ? 'strong'
                : ((share >= 0.40 && questionsCount >= 2) ? 'moderate' : 'thin');
} else {
  // Cohort size unavailable - fall back to the old absolute rule rather than
  // silently labelling every insight thin.
  corroboration = (sessionsCount >= 3 && questionsCount >= 3) ? 'strong'
                : ((sessionsCount >= 2 && questionsCount >= 2) ? 'moderate' : 'thin');
}

const supported = Boolean(out.supported) && picked.length > 0;
return [{ json: { supported: supported, name: out.name || base.name, statement: out.statement || base.statement, quotes: picked, finding_ids: base.finding_ids, attached_ids: base.attached_ids || [], findings_count: findingsCount, questions_count: questionsCount, sessions_count: sessionsCount, cohort_sessions: cohort, corroboration: corroboration, supplementary: base.supplementary === true, raters_agreeing: base.raters_agreeing || 1, rater_models: base.rater_models || [], agreement_jaccard: (base.agreement_jaccard === undefined ? null : base.agreement_jaccard), alt_statement: base.alt_statement || null, quotes_dropped: (out.quotes || []).length - picked.length, quotes_dropped_no_timestamp: droppedNoTimestamp, quotes_dropped_dup_moment: droppedDupMoment } }];

const proposed = $input.all().map(i => i.json);
const findings = $('Aggregate Findings').first().json.findings || [];
const cited = new Set();
for (const p of proposed) { for (const id of (p.finding_ids || [])) { cited.add(String(id)); } }
const uncovered = [];
for (const f of findings) {
  if (cited.has(String(f.finding_id))) { continue; }
  if (f.is_minority) { continue; }
  uncovered.push({ finding_id: f.finding_id, question: f.question, name: f.name, definition: f.definition, sessions: f.sessions });
}
const existing = proposed.map(p => ({ name: p.name, statement: p.statement }));
return [{ json: { uncovered: uncovered, existing: existing, uncovered_count: uncovered.length, proposed_count: proposed.length } }];

