const first = $('Verify Finding Refs B').all().map(i => i.json);
const raw = $input.first().json;
const extra = (raw.output && raw.output.insights) || raw.insights || [];
const findings = $('Aggregate Findings').first().json.findings || [];
const byId = new Map();
for (const f of findings) { byId.set(String(f.finding_id), f); }
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const out = [];
const existingNames = new Set();
for (const p of first) {
  out.push({ json: p });
  existingNames.add(String(p.name || '').toLowerCase().trim());
}
for (const ins of extra) {
  const ids = [];
  const seen = new Set();
  for (const id of (ins.finding_ids || [])) {
    const s = String(id);
    if (!uuidRegex.test(s)) { continue; }
    if (!byId.has(s)) { continue; }
    if (seen.has(s)) { continue; }
    seen.add(s);
    ids.push(s);
  }
  if (ids.length === 0) { continue; }
  const nm = String(ins.name || '').toLowerCase().trim();
  if (existingNames.has(nm)) { continue; }
  existingNames.add(nm);
  const questions = new Set();
  for (const id of ids) { questions.add(String(byId.get(id).question_id)); }
  out.push({ json: { name: ins.name, statement: ins.statement, finding_ids: ids, findings_count: ids.length, questions_count: questions.size, refs_dropped: (ins.finding_ids || []).length - ids.length, supplementary: true } });
}
return out;

// Resolve the adjudicator's index groups into real insights. The model decided
// grouping and CHOSE which existing statement to show; it did not write one.
// Every citation, count and corroboration figure is computed here from the
// resolved findings, so the evidence chain cannot be altered by the model.
const raw = $input.first().json;
const groups = (raw.output && raw.output.groups) || raw.groups || [];
const A = $('Combine Insights').all().map(i => i.json);
const B = $('Combine Insights B').all().map(i => i.json);
const findings = $('Aggregate Findings').first().json.findings || [];
const byId = new Map();
for (const f of findings) { byId.set(String(f.finding_id), f); }

const MODEL_A = 'gpt-5.4';
const MODEL_B = 'claude-opus-5';

function jaccard(sx, sy) {
  let inter = 0;
  for (const v of sx) { if (sy.has(v)) { inter++; } }
  const uni = sx.size + sy.size - inter;
  return uni === 0 ? 0 : inter / uni;
}
function questionsFor(ids) {
  const qs = new Set();
  for (const id of ids) { const f = byId.get(String(id)); if (f) { qs.add(String(f.question_id)); } }
  return qs.size;
}

const seenA = new Set();
const seenB = new Set();
const out = [];
let fallbacks = 0;

for (const g of groups) {
  const ai = (g.a || []).filter(i => Number.isInteger(i) && i >= 0 && i < A.length && !seenA.has(i));
  const bi = (g.b || []).filter(i => Number.isInteger(i) && i >= 0 && i < B.length && !seenB.has(i));
  if (ai.length === 0 && bi.length === 0) { continue; }
  for (const i of ai) { seenA.add(i); }
  for (const i of bi) { seenB.add(i); }

  const setA = new Set();
  for (const i of ai) { for (const id of (A[i].finding_ids || [])) { setA.add(String(id)); } }
  const setB = new Set();
  for (const i of bi) { for (const id of (B[i].finding_ids || [])) { setB.add(String(id)); } }
  const idList = Array.from(new Set([...setA, ...setB]));
  if (idList.length === 0) { continue; }

  const constituents = [...ai.map(i => A[i]), ...bi.map(i => B[i])];

  // The chosen statement is used VERBATIM - no synthesis, so no compression
  // loss. If the model's choice is out of range, fall back deterministically to
  // the longest constituent statement rather than trusting a bad index.
  let primaryText = null;
  const side = String(g.primary_side || '').toLowerCase();
  const pidx = Number(g.primary_index);
  if (side === 'a' && ai.indexOf(pidx) !== -1) { primaryText = A[pidx].statement; }
  else if (side === 'b' && bi.indexOf(pidx) !== -1) { primaryText = B[pidx].statement; }
  if (!primaryText) {
    fallbacks++;
    primaryText = constituents.map(c => String(c.statement || '')).sort((x, y) => y.length - x.length)[0];
  }
  const others = constituents.map(c => String(c.statement || '')).filter(s => s && s !== primaryText);
  const altText = others.length ? others.join('\n\n') : null;

  const models = [];
  if (ai.length) { models.push(MODEL_A); }
  if (bi.length) { models.push(MODEL_B); }

  out.push({ json: {
    name: g.name || constituents[0].name,
    statement: primaryText,
    alt_statement: altText,
    finding_ids: idList,
    findings_count: idList.length,
    questions_count: questionsFor(idList),
    supplementary: constituents.every(x => x.supplementary === true),
    raters_agreeing: models.length,
    rater_models: models,
    agreement_jaccard: (ai.length && bi.length) ? Math.round(jaccard(setA, setB) * 1000) / 1000 : null,
    merged_from_a: ai.length,
    merged_from_b: bi.length,
  } });
}

// Safety net: anything the adjudicator omits survives as a single-analyst entry
// rather than disappearing.
let orphans = 0;
for (let i = 0; i < A.length; i++) {
  if (seenA.has(i)) { continue; }
  orphans++;
  out.push({ json: { ...A[i], alt_statement: null, raters_agreeing: 1, rater_models: [MODEL_A], agreement_jaccard: null, merged_from_a: 1, merged_from_b: 0, orphaned: true } });
}
for (let i = 0; i < B.length; i++) {
  if (seenB.has(i)) { continue; }
  orphans++;
  out.push({ json: { ...B[i], alt_statement: null, raters_agreeing: 1, rater_models: [MODEL_B], agreement_jaccard: null, merged_from_a: 0, merged_from_b: 1, orphaned: true } });
}

const stats = { analyst_a: A.length, analyst_b: B.length, groups_returned: groups.length, final: out.length, both_raters: out.filter(o => o.json.raters_agreeing === 2).length, orphans_recovered: orphans, primary_fallbacks: fallbacks };
for (const o of out) { o.json._stats = stats; }
return out;

// Build INDEXED lists for the adjudicator. It never sees or emits finding_ids -
// it refers to insights by index only. Two reasons: the evidence chain stays
// deterministic because code resolves indices to citations, so the model cannot
// drop or invent one; and re-emitting hundreds of UUIDs is thousands of output
// tokens, which is exactly what exhausted Claude's budget earlier.
const A = $('Combine Insights').all().map(i => i.json);
const B = $('Combine Insights B').all().map(i => i.json);

function jaccard(x, y) {
  const sx = new Set((x || []).map(String));
  const sy = new Set((y || []).map(String));
  let inter = 0;
  for (const v of sx) { if (sy.has(v)) { inter++; } }
  const uni = sx.size + sy.size - inter;
  return uni === 0 ? 0 : inter / uni;
}

const a_list = A.map((x, i) => ({ i: i, name: x.name, statement: x.statement, cites: (x.finding_ids || []).length, questions: x.questions_count }));
const b_list = B.map((x, i) => ({ i: i, name: x.name, statement: x.statement, cites: (x.finding_ids || []).length, questions: x.questions_count }));

// Evidence overlap offered as a HINT only. It under-reads agreement when the
// two analysts partition at different granularity, which is the whole reason
// this step is no longer a pure overlap match.
const overlap = [];
for (let i = 0; i < A.length; i++) {
  const row = [];
  for (let j = 0; j < B.length; j++) {
    const s = jaccard(A[i].finding_ids, B[j].finding_ids);
    if (s > 0.05) { row.push({ b: j, overlap: Math.round(s * 100) / 100 }); }
  }
  row.sort((p, q) => q.overlap - p.overlap);
  overlap.push({ a: i, top: row.slice(0, 4) });
}

return [{ json: { a_list: a_list, b_list: b_list, overlap: overlap, a_count: A.length, b_count: B.length } }];

